local function taunt(ctx,e)for _,k in ipairs(ctx:entity(e).keywords)do if k=="taunt"then return true end end return false end
return {api_version=1,id="EX1_002",name="The Black Knight",text="<b>Tradeable</b>\n <b>Battlecry:</b> Destroy an  enemy minion with <b>Taunt</b>.",set="EXPERT1",type="minion",rarity="legendary",cost=4,attack=4,health=4,tags={"undead"},keywords={"tradeable","battlecry"},target_mode="required_if_available",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:enemy_minions(self))do if taunt(ctx,e)then r[#r+1]=e end end;return r end,on_battlecry=function(ctx,self,target)if target then ctx:destroy(target)end end}
